CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text UNIQUE NOT NULL, password_hash text NOT NULL, role text NOT NULL DEFAULT 'operator', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS wallets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid REFERENCES users(id), chain text NOT NULL, address text NOT NULL, label text NOT NULL, encrypted_key_ref text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(chain,address));
CREATE TABLE IF NOT EXISTS projects (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid REFERENCES users(id), name text NOT NULL, chain text NOT NULL, metadata jsonb NOT NULL DEFAULT '{}', status text NOT NULL DEFAULT 'draft', version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS project_versions (id bigserial PRIMARY KEY, project_id uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE, version integer NOT NULL, metadata jsonb NOT NULL DEFAULT '{}', status text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(project_id,version));
CREATE TABLE IF NOT EXISTS project_deployments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE, chain text NOT NULL, network text NOT NULL, contract_address text NOT NULL, transaction_hash text, status text NOT NULL, deployed_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS operation_jobs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), kind text NOT NULL, status text NOT NULL DEFAULT 'queued', idempotency_key text UNIQUE NOT NULL, payload jsonb NOT NULL, result jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_logs (id bigserial PRIMARY KEY, actor_id uuid, action text NOT NULL, resource_type text NOT NULL, resource_id text, ip inet, detail jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS auth_rate_limits (bucket text PRIMARY KEY, attempts integer NOT NULL DEFAULT 0, reset_at timestamptz NOT NULL, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS auth_sessions (session_hash text PRIMARY KEY, email text NOT NULL, ip_hash text, user_agent text, expires_at timestamptz NOT NULL, revoked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS automation_rules (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, kind text NOT NULL, enabled boolean NOT NULL DEFAULT true, schedule_minutes integer NOT NULL DEFAULT 15 CHECK(schedule_minutes BETWEEN 1 AND 10080), condition jsonb NOT NULL DEFAULT '{}', channels jsonb NOT NULL DEFAULT '[]', next_run_at timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS notification_channels (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), kind text NOT NULL, name text NOT NULL, destination text NOT NULL, enabled boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS automation_jobs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), rule_id uuid REFERENCES automation_rules(id) ON DELETE SET NULL, rule_name text NOT NULL, kind text NOT NULL, status text NOT NULL, attempt integer NOT NULL DEFAULT 1, dry_run boolean NOT NULL DEFAULT true, detail jsonb NOT NULL DEFAULT '{}', error text, created_at timestamptz NOT NULL DEFAULT now(), finished_at timestamptz);
CREATE TABLE IF NOT EXISTS chat_challenges (id uuid PRIMARY KEY, chain text NOT NULL CHECK(chain IN ('EVM','SOL')), address text NOT NULL, device_id uuid NOT NULL, device_public_key text NOT NULL, message text NOT NULL, expires_at timestamptz NOT NULL, used_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS chat_devices (device_id uuid PRIMARY KEY, chain text NOT NULL CHECK(chain IN ('EVM','SOL')), address text NOT NULL, public_key text NOT NULL, updated_at timestamptz NOT NULL DEFAULT now(), revoked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(chain,address,device_id));
CREATE TABLE IF NOT EXISTS chat_envelopes (id bigserial PRIMARY KEY, message_id uuid UNIQUE NOT NULL, conversation_id uuid NOT NULL, version smallint NOT NULL DEFAULT 1 CHECK(version=1), sender_device_id uuid NOT NULL REFERENCES chat_devices(device_id), recipient_device_id uuid NOT NULL REFERENCES chat_devices(device_id), client_timestamp timestamptz NOT NULL, salt text NOT NULL, iv text NOT NULL, ciphertext text NOT NULL CHECK(length(ciphertext)<=87384), expires_at timestamptz NOT NULL, ack_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), CHECK(expires_at>created_at AND expires_at<=created_at+interval '30 days'));
CREATE TABLE IF NOT EXISTS chat_auth_challenges (id uuid PRIMARY KEY, chain text NOT NULL CHECK(chain IN ('EVM','SOL')), address text NOT NULL, device_id uuid NOT NULL, device_public_key text NOT NULL, device_key_hash text NOT NULL CHECK(device_key_hash ~ '^[a-f0-9]{64}$'), nonce_hash text NOT NULL CHECK(nonce_hash ~ '^[a-f0-9]{64}$'), challenge_message text NOT NULL, issued_at timestamptz NOT NULL, expires_at timestamptz NOT NULL, used_at timestamptz, CHECK(expires_at>issued_at AND expires_at<=issued_at+interval '5 minutes'));
CREATE TABLE IF NOT EXISTS chat_messages (message_id uuid PRIMARY KEY, conversation_id uuid NOT NULL, sender_chain text NOT NULL CHECK(sender_chain IN ('EVM','SOL')), sender_address text NOT NULL, sender_device_id uuid NOT NULL REFERENCES chat_devices(device_id), recipient_chain text NOT NULL CHECK(recipient_chain IN ('EVM','SOL')), recipient_address text NOT NULL, recipient_device_id uuid NOT NULL REFERENCES chat_devices(device_id), client_timestamp timestamptz NOT NULL, salt text NOT NULL, iv text NOT NULL, ciphertext text NOT NULL CHECK(length(ciphertext)<=87384), envelope_hash text NOT NULL CHECK(envelope_hash ~ '^[a-f0-9]{64}$'), received_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL, acked_at timestamptz, CHECK(expires_at>received_at AND expires_at<=received_at+interval '30 days'));
CREATE INDEX IF NOT EXISTS idx_jobs_status_created ON operation_jobs(status,created_at); CREATE INDEX IF NOT EXISTS idx_audit_actor_created ON audit_logs(actor_id,created_at DESC); CREATE INDEX IF NOT EXISTS idx_auth_rate_limits_reset ON auth_rate_limits(reset_at); CREATE INDEX IF NOT EXISTS idx_auth_sessions_email_active ON auth_sessions(email,expires_at) WHERE revoked_at IS NULL; CREATE INDEX IF NOT EXISTS idx_projects_chain_status ON projects(chain,status); CREATE INDEX IF NOT EXISTS idx_project_versions_project ON project_versions(project_id,version DESC); CREATE INDEX IF NOT EXISTS idx_project_deployments_project ON project_deployments(project_id,deployed_at DESC); CREATE INDEX IF NOT EXISTS idx_automation_rules_due ON automation_rules(enabled,next_run_at); CREATE INDEX IF NOT EXISTS idx_automation_jobs_status_created ON automation_jobs(status,created_at DESC); CREATE INDEX IF NOT EXISTS idx_chat_challenges_expiry ON chat_challenges(expires_at) WHERE used_at IS NULL; CREATE INDEX IF NOT EXISTS idx_chat_devices_identity ON chat_devices(chain,address,updated_at DESC) WHERE revoked_at IS NULL; CREATE INDEX IF NOT EXISTS idx_chat_inbox_cursor ON chat_envelopes(recipient_device_id,id) WHERE ack_at IS NULL;
CREATE INDEX IF NOT EXISTS idx_chat_auth_challenges_expiry ON chat_auth_challenges(expires_at); CREATE INDEX IF NOT EXISTS idx_chat_devices_address ON chat_devices(chain,address,revoked_at); CREATE INDEX IF NOT EXISTS idx_chat_messages_recipient_poll ON chat_messages(recipient_device_id,acked_at,received_at,message_id); CREATE INDEX IF NOT EXISTS idx_chat_messages_expiry ON chat_messages(expires_at);
